		[DllImport("VuforiaEngine", EntryPoint = "vuEngineGetAreaTargetCaptureController", CallingConvention = CallingConvention.StdCall)]
		public static extern Result EngineGetAreaTargetCaptureController(Engine* engine, Controller** controller);

		/// <summary>
		/// Create a new capture with the specified configuration
		/// Any previously created capture has to be destroyed before creating a new capture.
		/// This function creates an Area Target capture based on the specified configuration.
		/// On successful creation the capture has status
		/// @ref VU_AREA_TARGET_CAPTURE_STATUS_INITIALIZED,
		/// unless the configuration&apos;s start flag is VU_TRUE, then the capture has status
		/// @ref VU_AREA_TARGET_CAPTURE_STATUS_PREPARING.
		/// If creation of the capture fails,
		/// then VU_FAILED is returned and the optional error parameter will hold an error code
		/// that reflects the cause of the error.
		/// If Engine is not running and the configuration&apos;s start flag is VU_TRUE,
		/// then on successful creation the capture has status
		/// @ref VU_AREA_TARGET_CAPTURE_STATUS_PAUSED
		/// and status info
		/// @ref VU_AREA_TARGET_CAPTURE_STATUS_INFO_SUSPENDED.
		/// The capture
		/// will then be started automatically during the next call to
		/// @ref vuEngineStart().
		/// Area Target Capture Controller
		/// The configuration for the new capture
		/// Output variable storing the newly created capture
		/// Optional output variable providing additional error information. Can be NULL.
		/// VU_SUCCESS on successful creation of the capture, VU_FAILED otherwise
		/// </summary>
		[DllImport("VuforiaEngine", EntryPoint = "vuAreaTargetCaptureControllerCreateAreaTargetCapture", CallingConvention = CallingConvention.StdCall)]
		public static extern Result AreaTargetCaptureControllerCreateAreaTargetCapture(Controller* controller, AreaTargetCaptureConfig* config, AreaTargetCapture** capture, AreaTargetCaptureCreationError* error);

