		/// Stop a running or paused capture
		/// The capture stops data acquisition, and switches to status
		/// @ref VU_AREA_TARGET_CAPTURE_STATUS_STOPPED.
		/// An Area Target can be generated only when the capture is stopped.
		/// This function fails if Engine is not running.
		/// VU_SUCCESS if the capture is in status
		/// @ref VU_AREA_TARGET_CAPTURE_STATUS_PREPARING,
		/// @ref VU_AREA_TARGET_CAPTURE_STATUS_CAPTURING,
		/// or
		/// @ref VU_AREA_TARGET_CAPTURE_STATUS_PAUSED
		/// and stop is successful, VU_FAILED otherwise
		/// </summary>
		[DllImport("VuforiaEngine", EntryPoint = "vuAreaTargetCaptureStop", CallingConvention = CallingConvention.StdCall)]
		public static extern Result AreaTargetCaptureStop(AreaTargetCapture* capture);

		/// <summary>
		/// Pause a running capture
		/// Data acquisition of the capture can be paused and resumed.
		/// @ref vuAreaTargetCapturePause()
		/// pauses data acquisition and switches the capture to status
		/// @ref VU_AREA_TARGET_CAPTURE_STATUS_PAUSED.
		/// @ref vuAreaTargetCaptureResume()
		/// resumes data acquisition and switches the capture to the status it
		/// was in before the pause.
		/// If Engine is stopped while a capture is running, then the capture will be automatically
		/// paused during
		/// @ref vuEngineStop(),
		/// and it will be automatically resumed during the next call
		/// to
		/// @ref vuEngineStart().
		/// A capture that is automatically paused by Engine has status info
		/// @ref VU_AREA_TARGET_CAPTURE_STATUS_INFO_SUSPENDED.
		/// This function fails if Engine is not running.
		/// VU_SUCCESS if the capture is in status
		/// @ref VU_AREA_TARGET_CAPTURE_STATUS_PREPARING
		/// or
		/// @ref VU_AREA_TARGET_CAPTURE_STATUS_CAPTURING
		/// and pause is successful, VU_FAILED otherwise
		/// </summary>
		[DllImport("VuforiaEngine", EntryPoint = "vuAreaTargetCapturePause", CallingConvention = CallingConvention.StdCall)]
		public static extern Result AreaTargetCapturePause(AreaTargetCapture* capture);

